BUILDER = '// apps/web/lib/inevitable-standard/buildInsiderInsightsReport.ts\n//\n// Pure selection + assembly for the approved five-section Insider Insights\n// report. The Figma information architecture stays compact; the intelligence\n// inside it follows the master-report evidence hierarchy:\n//\n//   pillar evidence -> Constraint Engine -> approach hypothesis -> secondary\n//   influence -> live-conversation validation.\n//\n// The approach shapes interpretation. It never creates a risk signal or\n// overrides stronger diagnostic evidence.\n\nimport {\n  garFromRisk,\n  getInsiderInsightsForApproach,\n  INSIDER_INSIGHTS_SOURCE_VERSION,\n  pillarIdFromKey,\n  selectAccountability,\n  selectAvoidedQuestion,\n  selectChallengeSequenceForPillar,\n  selectCoreProfile,\n  selectDirectionalPair,\n  selectNextStepPositioning,\n  selectObjection,\n  selectPillarState,\n  selectPostSaleCoachingForPillar,\n  selectPrimaryConstraint,\n  selectQuestionsByPrimary,\n  selectSecondaryInfluence,\n  selectStrongestPillar,\n  type InsiderApproachCode,\n  type InsiderApproachName,\n  type InsiderGar,\n  type InsiderPillarKey,\n  type InsiderPillarState,\n  type InsiderRiskSignal,\n} from "./content/insiderInsights";\n\n/* -------------------------------------------------------------------------- */\n/* Vocabulary                                                                  */\n/* -------------------------------------------------------------------------- */\n\nconst PILLAR_KEYS: InsiderPillarKey[] = [\n  "identity",\n  "positioning",\n  "offer",\n  "sales",\n  "revenue_model",\n  "decision",\n];\n\nconst PILLAR_LABEL: Record<InsiderPillarKey, string> = {\n  identity: "Identity",\n  positioning: "Positioning",\n  offer: "Offer",\n  sales: "Sales",\n  revenue_model: "Revenue Model",\n  decision: "Decision",\n};\n\nconst PILLAR_DESCRIPTOR: Record<InsiderPillarKey, string> = {\n  identity: "Authority, commercial confidence and willingness to lead.",\n  positioning: "How clearly the market understands and chooses you.",\n  offer: "The clarity, boundaries and repeatability of what you sell.",\n  sales: "Discovery, conversion and the quality of the buying path.",\n  revenue_model: "Margin, retention, owner reward and transferability.",\n  decision: "Commercial focus, follow-through and decision discipline.",\n};\n\nconst APPROACH_LABEL: Record<InsiderApproachCode, string> = {\n  A: "Future-Led",\n  B: "Connection-Led",\n  C: "Timing-Led",\n  D: "Evidence-Led",\n};\n\nconst APPROACH_NAME_LABEL: Record<InsiderApproachName, string> = {\n  FUTURE_LED: "Future-Led",\n  CONNECTION_LED: "Connection-Led",\n  TIMING_LED: "Timing-Led",\n  EVIDENCE_LED: "Evidence-Led",\n  BALANCED: "Balanced",\n};\n\nconst APPROACH_NAME_BY_CODE: Record<InsiderApproachCode, InsiderApproachName> = {\n  A: "FUTURE_LED",\n  B: "CONNECTION_LED",\n  C: "TIMING_LED",\n  D: "EVIDENCE_LED",\n};\n\nconst GAR_LABEL: Record<InsiderGar, string> = {\n  GREEN: "Green",\n  AMBER: "Amber",\n  RED: "Red",\n};\n\nconst FALSE_CONSTRAINT_LABEL: Record<string, string> = {\n  lead_volume: "“Not enough leads”",\n  price_too_high: "“The price is too high”",\n  new_offer_needed: "“We need a new or bigger offer”",\n  needs_systems: "“We need better systems first”",\n};\n\nconst FALSE_CONSTRAINT_KEY: Record<\n  string,\n  "MORE_LEADS" | "PRICE_TOO_HIGH" | "NEW_OFFER" | "BETTER_SYSTEMS"\n> = {\n  lead_volume: "MORE_LEADS",\n  price_too_high: "PRICE_TOO_HIGH",\n  new_offer_needed: "NEW_OFFER",\n  needs_systems: "BETTER_SYSTEMS",\n};\n\n/**\n * Figma shows a four-card evidence strip beneath Q13. These pairs represent\n * the most useful evidence to place beside each supported perceived problem.\n * Primary and Secondary are appended after these, so the cards always include\n * the live diagnosis rather than becoming a generic template.\n */\nconst FALSE_CONSTRAINT_EVIDENCE: Record<string, InsiderPillarKey[]> = {\n  lead_volume: ["positioning", "offer"],\n  price_too_high: ["offer", "identity"],\n  new_offer_needed: ["offer", "positioning"],\n  needs_systems: ["revenue_model", "sales"],\n};\n\n/* -------------------------------------------------------------------------- */\n/* Output types                                                                */\n/* -------------------------------------------------------------------------- */\n\nexport type InsiderPillarSnapshot = {\n  key: InsiderPillarKey;\n  label: string;\n  descriptor: string;\n  percentage: number;\n  gar: InsiderGar;\n  garLabel: string;\n};\n\nexport type InsiderSignalRow = { label: string; text: string };\n\nexport type InsiderTagKind =\n  | "HYPOTHESIS TO VALIDATE"\n  | "LISTEN FOR"\n  | "DO NOT ASSUME"\n  | "GREEN LEVERAGE";\n\nexport type InsiderTag = { kind: InsiderTagKind; text: string };\n\nexport type InsiderFounderWord = {\n  questionNumber: 13 | 29;\n  prompt: string;\n  quote: string;\n  pillar: {\n    label: string;\n    gar: InsiderGar;\n    garLabel: string;\n    percentage: number;\n  } | null;\n  evidencePillars: InsiderPillarSnapshot[];\n  tags: InsiderTag[];\n  riskSignal: { label: string; text: string; adviserResponse: string | null } | null;\n};\n\nexport type InsiderSequenceStep = {\n  step: number;\n  title: string;\n  instruction: string;\n  example: string | null;\n};\n\nexport type InsiderInsightsReport = {\n  meta: {\n    approachCode: InsiderApproachCode;\n    approachLabel: string;\n    secondaryInfluence: InsiderApproachName | null;\n    secondaryInfluenceLabel: string | null;\n    primaryConstraint: { key: InsiderPillarKey; label: string } | null;\n    secondaryConstraint: { key: InsiderPillarKey; label: string } | null;\n    strongestPillar: { key: InsiderPillarKey; label: string; percentage: number } | null;\n    sourceVersion: string;\n    generatedAt: string | null;\n    taker: { fullName: string; email: string; company: string };\n    test: { name: string };\n    org: { name: string };\n  };\n  snapshot: {\n    readinessPercentage: number;\n    readinessLabel: string | null;\n    primaryApproach: { label: string; percentage: number };\n    secondaryApproach: { label: string; percentage: number | null } | null;\n    approachMix: Array<{ code: InsiderApproachCode; label: string; percentage: number }>;\n    primaryConstraint: InsiderPillarSnapshot | null;\n    secondaryConstraint: InsiderPillarSnapshot | null;\n    strongestPillar: InsiderPillarSnapshot | null;\n    falseConstraint: { label: string; note: string } | null;\n    priorityOrder: Array<{ key: InsiderPillarKey; label: string }>;\n    pillars: InsiderPillarSnapshot[];\n  };\n  predictiveSignals: InsiderSignalRow[];\n  foundersWords: InsiderFounderWord[];\n  sequenceIntro: string | null;\n  suggestedSequence: InsiderSequenceStep[];\n  sequenceCaution: string | null;\n  objective: string | null;\n  qaFlags: string[];\n};\n\n/* -------------------------------------------------------------------------- */\n/* Input normalisation                                                         */\n/* -------------------------------------------------------------------------- */\n\ntype LooseRecord = Record<string, unknown>;\n\nfunction asRecord(value: unknown): LooseRecord {\n  return value && typeof value === "object" && !Array.isArray(value)\n    ? (value as LooseRecord)\n    : {};\n}\n\nfunction clampPct(value: unknown): number {\n  const n = Number(value);\n  if (!Number.isFinite(n)) return 0;\n  return Math.max(0, Math.min(100, Math.round(n * 10) / 10));\n}\n\nfunction isPillarKey(value: unknown): value is InsiderPillarKey {\n  return typeof value === "string" && PILLAR_KEYS.includes(value as InsiderPillarKey);\n}\n\nfunction isApproachCode(value: unknown): value is InsiderApproachCode {\n  return value === "A" || value === "B" || value === "C" || value === "D";\n}\n\nfunction cleanText(value: unknown): string {\n  return typeof value === "string" ? value.trim() : "";\n}\n\nfunction firstParagraph(value: unknown): string {\n  const text = cleanText(value);\n  if (!text) return "";\n  return (text.split(/\\n{2,}/)[0] ?? "").trim();\n}\n\nfunction firstSentence(value: unknown): string {\n  const para = firstParagraph(value);\n  if (!para) return "";\n  const match = para.match(/^.*?[.?!](?=\\s|$)/);\n  return (match ? match[0] : para).trim();\n}\n\n/** Keep the Figma glance table concise without changing the evidence source. */\nfunction compact(value: unknown, max = 360): string {\n  const para = firstParagraph(value).replace(/\\s+/g, " ").trim();\n  if (!para || para.length <= max) return para;\n  const candidate = para.slice(0, max + 1);\n  const lastSentence = Math.max(\n    candidate.lastIndexOf(". "),\n    candidate.lastIndexOf("? "),\n    candidate.lastIndexOf("! "),\n  );\n  if (lastSentence >= Math.floor(max * 0.55)) {\n    return candidate.slice(0, lastSentence + 1).trim();\n  }\n  const lastSpace = candidate.lastIndexOf(" ");\n  return `${candidate.slice(0, Math.max(lastSpace, max - 20)).trim()}…`;\n}\n\nfunction joinCompact(primary: unknown, nuance: unknown): string {\n  const a = compact(primary, 270);\n  const b = firstSentence(nuance);\n  if (!a) return compact(b);\n  if (!b || a.includes(b)) return a;\n  return compact(`${a} ${b}`, 380);\n}\n\nconst QUOTE_STOPLIST = new Set([\n  "test",\n  "testing",\n  "tests",\n  "na",\n  "n/a",\n  "none",\n  "nothing",\n  "asdf",\n  "xxx",\n  "todo",\n  "tbd",\n]);\n\nfunction isMeaningfulFreeText(value: unknown): boolean {\n  const text = cleanText(value);\n  if (text.length < 5) return false;\n  if (QUOTE_STOPLIST.has(text.toLowerCase())) return false;\n  return /[a-z]{3,}/i.test(text);\n}\n\n/** Token-overlap pick. A risk signal must still match the founder\'s answer. */\nfunction pickRiskSignal(\n  signals: InsiderRiskSignal[],\n  context: string,\n): InsiderRiskSignal | null {\n  const ctxTokens = new Set(context.toLowerCase().match(/[a-z]{4,}/g) ?? []);\n  if (ctxTokens.size === 0) return null;\n  let best: { signal: InsiderRiskSignal; score: number } | null = null;\n  for (const signal of signals) {\n    const tokens = `${signal.label ?? ""} ${signal.text ?? ""}`\n      .toLowerCase()\n      .match(/[a-z]{4,}/g) ?? [];\n    const score = tokens.filter((token) => ctxTokens.has(token)).length;\n    if (!best || score > best.score) best = { signal, score };\n  }\n  return best && best.score >= 3 ? best.signal : null;\n}\n\nfunction toRiskSignalCard(\n  signal: InsiderRiskSignal | null,\n): InsiderFounderWord["riskSignal"] {\n  if (!signal) return null;\n  const text = cleanText(signal.text);\n  if (!text) return null;\n  return {\n    label: cleanText(signal.label) || "Risk signal",\n    text,\n    adviserResponse: cleanText(signal.adviserResponse) || null,\n  };\n}\n\nfunction evidenceStripKeys({\n  ruleId,\n  primary,\n  secondary,\n  pillars,\n}: {\n  ruleId: string | null;\n  primary: InsiderPillarKey | null;\n  secondary: InsiderPillarKey | null;\n  pillars: InsiderPillarSnapshot[];\n}): InsiderPillarKey[] {\n  const keys: InsiderPillarKey[] = [];\n  const add = (key: InsiderPillarKey | null | undefined) => {\n    if (key && !keys.includes(key)) keys.push(key);\n  };\n\n  for (const key of ruleId ? FALSE_CONSTRAINT_EVIDENCE[ruleId] ?? [] : []) add(key);\n  add(primary);\n  add(secondary);\n\n  // If fewer than four are diagnostic-specific, fill with the next pillars in\n  // the diagnosis-led severity pattern. This keeps the Figma strip useful.\n  for (const pillar of [...pillars].sort(\n    (a, b) =>\n      a.percentage - b.percentage ||\n      PILLAR_KEYS.indexOf(a.key) - PILLAR_KEYS.indexOf(b.key),\n  )) {\n    add(pillar.key);\n    if (keys.length >= 4) break;\n  }\n\n  return keys.slice(0, 4);\n}\n\nexport type BuildInsiderInsightsInput = {\n  score: unknown;\n  taker?: { fullName?: string | null; email?: string | null; company?: string | null } | null;\n  test?: { name?: string | null } | null;\n  org?: { name?: string | null } | null;\n  completedAt?: string | null;\n};\n\n/* -------------------------------------------------------------------------- */\n/* Build                                                                       */\n/* -------------------------------------------------------------------------- */\n\nexport function buildInsiderInsightsReport(\n  input: BuildInsiderInsightsInput,\n): InsiderInsightsReport | null {\n  const score = asRecord(input.score);\n  const approaches = asRecord(score.approaches);\n  const constraints = asRecord(score.constraints);\n  const overall = asRecord(score.overall);\n  const pillarsRaw = asRecord(score.pillars);\n  const contextAnswers = asRecord(score.context_answers);\n  const qaFlags: string[] = [];\n\n  /* --- approach ----------------------------------------------------------- */\n\n  const percentages = asRecord(approaches.percentages);\n  let approachCode: InsiderApproachCode | null = isApproachCode(approaches.dominant)\n    ? approaches.dominant\n    : null;\n\n  if (!approachCode) {\n    let best: { code: InsiderApproachCode; pct: number } | null = null;\n    for (const code of ["A", "B", "C", "D"] as InsiderApproachCode[]) {\n      const pct = Number(percentages[code]);\n      if (Number.isFinite(pct) && (!best || pct > best.pct)) best = { code, pct };\n    }\n    approachCode = best?.code ?? null;\n    if (approachCode) qaFlags.push("approaches.dominant missing — inferred from percentages");\n  }\n\n  if (!approachCode) return null;\n\n  const approachData = getInsiderInsightsForApproach(approachCode);\n  if (!approachData) return null;\n  const core = selectCoreProfile(approachCode);\n\n  let secondaryInfluence: InsiderApproachName | null = null;\n  if (approaches.secondary === "BALANCED") secondaryInfluence = "BALANCED";\n  else if (isApproachCode(approaches.secondary)) {\n    secondaryInfluence = APPROACH_NAME_BY_CODE[approaches.secondary];\n  }\n  const secondaryProfile = secondaryInfluence\n    ? selectSecondaryInfluence(approachCode, secondaryInfluence)\n    : null;\n\n  /* --- pillar evidence ---------------------------------------------------- */\n\n  const pillars: InsiderPillarSnapshot[] = PILLAR_KEYS.map((key) => {\n    const result = asRecord(pillarsRaw[key]);\n    const gar = garFromRisk(result.risk as string | undefined);\n    return {\n      key,\n      label: PILLAR_LABEL[key],\n      descriptor: PILLAR_DESCRIPTOR[key],\n      percentage: clampPct(result.percentage),\n      gar,\n      garLabel: GAR_LABEL[gar],\n    };\n  });\n  const pillarByKey = new Map(pillars.map((pillar) => [pillar.key, pillar]));\n\n  /* --- constraint diagnosis --------------------------------------------- */\n\n  const primaryKey: InsiderPillarKey | null = isPillarKey(constraints.primary_constraint)\n    ? constraints.primary_constraint\n    : null;\n  const secondaryKey: InsiderPillarKey | null = isPillarKey(constraints.secondary_constraint)\n    ? constraints.secondary_constraint\n    : null;\n\n  if (!primaryKey) {\n    qaFlags.push(\n      "constraints.primary_constraint missing — objection, sequence and objective fall back to approach content",\n    );\n  }\n\n  const primaryPillar = primaryKey ? pillarByKey.get(primaryKey) ?? null : null;\n  const secondaryPillar = secondaryKey ? pillarByKey.get(secondaryKey) ?? null : null;\n  const decisionPillar = pillarByKey.get("decision") ?? null;\n\n  const strongest =\n    [...pillars].sort(\n      (a, b) =>\n        b.percentage - a.percentage ||\n        PILLAR_KEYS.indexOf(a.key) - PILLAR_KEYS.indexOf(b.key),\n    )[0] ?? null;\n\n  // Never trust the legacy stored Priority Fix Order. Older assessments may\n  // still contain the pre-alignment Method-layer sort.\n  const priorityKeys: InsiderPillarKey[] = [];\n  if (primaryKey) priorityKeys.push(primaryKey);\n  if (secondaryKey && secondaryKey !== primaryKey) priorityKeys.push(secondaryKey);\n  for (const pillar of [...pillars].sort(\n    (a, b) =>\n      a.percentage - b.percentage ||\n      PILLAR_KEYS.indexOf(a.key) - PILLAR_KEYS.indexOf(b.key),\n  )) {\n    if (!priorityKeys.includes(pillar.key)) priorityKeys.push(pillar.key);\n  }\n\n  const falseConstraintRuleId =\n    typeof constraints.false_constraint_rule_id === "string"\n      ? constraints.false_constraint_rule_id\n      : null;\n\n  let falseConstraint: { label: string; note: string } | null = null;\n  if (falseConstraintRuleId && FALSE_CONSTRAINT_LABEL[falseConstraintRuleId]) {\n    const fcBlock =\n      approachData.falseConstraints?.core?.[FALSE_CONSTRAINT_KEY[falseConstraintRuleId]] ?? null;\n    const fcExplanation = cleanText(asRecord(constraints.false_constraint).explanation);\n    falseConstraint = {\n      label: FALSE_CONSTRAINT_LABEL[falseConstraintRuleId],\n      note:\n        cleanText(fcBlock?.diagnosticDirection) ||\n        fcExplanation ||\n        firstParagraph(fcBlock?.text),\n    };\n  }\n\n  const snapshot: InsiderInsightsReport["snapshot"] = {\n    readinessPercentage: clampPct(overall.percentage),\n    readinessLabel: cleanText(overall.label) || null,\n    primaryApproach: {\n      label: APPROACH_LABEL[approachCode],\n      percentage: clampPct(percentages[approachCode]),\n    },\n    secondaryApproach: secondaryInfluence\n      ? {\n          label: APPROACH_NAME_LABEL[secondaryInfluence],\n          percentage:\n            secondaryInfluence === "BALANCED" || !isApproachCode(approaches.secondary)\n              ? null\n              : clampPct(percentages[approaches.secondary]),\n        }\n      : null,\n    approachMix: (["A", "B", "C", "D"] as InsiderApproachCode[]).map((code) => ({\n      code,\n      label: APPROACH_LABEL[code],\n      percentage: clampPct(percentages[code]),\n    })),\n    primaryConstraint: primaryPillar,\n    secondaryConstraint: secondaryPillar,\n    strongestPillar: strongest,\n    falseConstraint,\n    priorityOrder: priorityKeys.map((key) => ({ key, label: PILLAR_LABEL[key] })),\n    pillars,\n  };\n\n  /* --- selected evidence blocks ----------------------------------------- */\n\n  const pc = primaryKey ? selectPrimaryConstraint(approachCode, primaryKey) : null;\n  const primaryState: InsiderPillarState | null =\n    primaryKey && primaryPillar\n      ? selectPillarState(approachCode, primaryKey, primaryPillar.gar)\n      : null;\n  const decisionState: InsiderPillarState | null = decisionPillar\n    ? selectPillarState(approachCode, "decision", decisionPillar.gar)\n    : null;\n  const strongestBlurb =\n    strongest ? selectStrongestPillar(approachCode, strongest.key) : null;\n  const directionalPair =\n    primaryKey && secondaryKey\n      ? selectDirectionalPair(approachCode, primaryKey, secondaryKey)\n      : null;\n  const objection = primaryKey ? selectObjection(approachCode, primaryKey) : null;\n  const accountability =\n    primaryKey && primaryPillar\n      ? selectAccountability(approachCode, primaryKey, primaryPillar.gar)\n      : null;\n  const challengeDetail = primaryKey\n    ? selectChallengeSequenceForPillar(approachCode, primaryKey)\n    : null;\n  const postSaleDetail = primaryKey\n    ? selectPostSaleCoachingForPillar(approachCode, primaryKey)\n    : null;\n\n  /* ====================================================================== */\n  /* 2. PREDICTIVE SIGNALS — evidence can override generic approach copy     */\n  /* ====================================================================== */\n\n  const predictiveSignals: InsiderSignalRow[] = [];\n  const pushSignal = (label: string, value: string) => {\n    const text = value.trim();\n    if (text) predictiveSignals.push({ label, text });\n    else qaFlags.push(`predictive signal "${label}" has no source content — row omitted`);\n  };\n\n  // Actual state evidence is first. Approach baseline is only the fallback.\n  pushSignal(\n    "How they think",\n    compact(primaryState?.howThisAffectsThinking) || compact(core?.howTheyThink),\n  );\n  pushSignal(\n    "How they decide",\n    compact(decisionState?.howThisAffectsDeciding) ||\n      compact(primaryState?.howThisAffectsDeciding) ||\n      compact(core?.howTheyDecide),\n  );\n  pushSignal(\n    "How they buy",\n    compact(primaryState?.howThisAffectsBuying) || compact(core?.howTheyBuy),\n  );\n\n  // Trust remains primarily approach-led, because this is communication\n  // guidance rather than a diagnostic claim.\n  pushSignal("What builds trust", compact(core?.trustBuilders));\n  pushSignal("What reduces trust", compact(core?.trustReducers));\n\n  pushSignal(\n    "Best communication style",\n    compact(primaryState?.howToCommunicate) || compact(core?.communicationStyle),\n  );\n\n  if (primaryKey) {\n    pushSignal(\n      "Likely objection",\n      compact(objection?.possibleLanguage) ||\n        compact(pc?.likelyBuyingObjectionTheme),\n    );\n    pushSignal(\n      "What may really be underneath it",\n      compact(pc?.whatIsReallyHappening) ||\n        compact(directionalPair?.text) ||\n        compact(objection?.whatMaySitUnderneath),\n    );\n  } else {\n    qaFlags.push(\n      "no primary constraint — Likely Objection / What May Really Be Underneath rows omitted",\n    );\n  }\n\n  // Buying/resistance are explicitly behavioural signals: hypotheses to\n  // observe, not findings created by the approach.\n  pushSignal("Buying signals", compact(approachData.buyingResistance?.buying));\n  pushSignal("Resistance signals", compact(approachData.buyingResistance?.resistance));\n\n  pushSignal(\n    "What to challenge",\n    compact(primaryState?.whatToChallenge) ||\n      compact(challengeDetail) ||\n      compact(core?.challengeGuidance),\n  );\n  pushSignal(\n    "What not to assume",\n    compact(primaryState?.whatNotToAssume) || compact(core?.whatNotToAssumeGeneral),\n  );\n  pushSignal(\n    "Coaching style",\n    joinCompact(\n      primaryState?.coachingImplication ||\n        postSaleDetail ||\n        accountability ||\n        core?.coachingStyle,\n      secondaryProfile?.coachingImplication,\n    ),\n  );\n\n  /* ====================================================================== */\n  /* 3. FOUNDER\'S OWN WORDS                                                  */\n  /* ====================================================================== */\n\n  const q13present = isMeaningfulFreeText(contextAnswers[13]);\n  const q29present = isMeaningfulFreeText(contextAnswers[29]);\n  const foundersWords: InsiderFounderWord[] = [];\n\n  const q13EvidenceKeys = evidenceStripKeys({\n    ruleId: falseConstraintRuleId,\n    primary: primaryKey,\n    secondary: secondaryKey,\n    pillars,\n  });\n\n  if (q13present) {\n    const tags: InsiderTag[] = [];\n\n    const hypothesis =\n      cleanText(pc?.whatIsReallyHappening) ||\n      cleanText(asRecord(constraints.false_constraint).explanation) ||\n      cleanText(directionalPair?.text);\n    if (hypothesis) {\n      tags.push({ kind: "HYPOTHESIS TO VALIDATE", text: compact(hypothesis, 440) });\n    }\n\n    if (primaryState?.whatToListenFor) {\n      tags.push({\n        kind: "LISTEN FOR",\n        text: compact(primaryState.whatToListenFor, 440),\n      });\n    }\n\n    if (primaryState?.whatNotToAssume) {\n      tags.push({\n        kind: "DO NOT ASSUME",\n        text: compact(primaryState.whatNotToAssume, 440),\n      });\n    }\n\n    if (strongest && strongest.gar !== "RED" && strongestBlurb) {\n      tags.push({\n        kind: "GREEN LEVERAGE",\n        text: compact(strongestBlurb, 440),\n      });\n    }\n\n    foundersWords.push({\n      questionNumber: 13,\n      prompt: "The biggest thing holding the business back",\n      quote: cleanText(contextAnswers[13]),\n      pillar: primaryPillar\n        ? {\n            label: primaryPillar.label,\n            gar: primaryPillar.gar,\n            garLabel: primaryPillar.garLabel,\n            percentage: primaryPillar.percentage,\n          }\n        : null,\n      evidencePillars: q13EvidenceKeys\n        .map((key) => pillarByKey.get(key))\n        .filter((pillar): pillar is InsiderPillarSnapshot => Boolean(pillar)),\n      tags,\n      // The approved Figma uses Q13 for diagnosis/hypothesis and Q29 for the\n      // answer-level risk card. Do not invent an extra risk callout here.\n      riskSignal: null,\n    });\n  }\n\n  if (q29present) {\n    const riskContext = [\n      cleanText(contextAnswers[29]),\n      "decision certainty analysis",\n      cleanText(pc?.approachMechanism),\n      cleanText(decisionState?.commercialConsequence),\n    ].join(" ");\n\n    foundersWords.push({\n      questionNumber: 29,\n      prompt: "A decision you know you need to make but have not made",\n      quote: cleanText(contextAnswers[29]),\n      pillar: decisionPillar\n        ? {\n            label: decisionPillar.label,\n            gar: decisionPillar.gar,\n            garLabel: decisionPillar.garLabel,\n            percentage: decisionPillar.percentage,\n          }\n        : null,\n      evidencePillars: [],\n      tags: [],\n      riskSignal: toRiskSignalCard(\n        pickRiskSignal(approachData.riskSignals ?? [], riskContext),\n      ),\n    });\n  }\n\n  if (foundersWords.length === 0) {\n    qaFlags.push("Q13 / Q29 free text is empty or filler — Founder\'s Own Words section is empty");\n  }\n\n  /* ====================================================================== */\n  /* 4. SUGGESTED SEQUENCE — Figma structure, evidence-led content          */\n  /* ====================================================================== */\n\n  const prosper = approachData.prosper;\n  const byPrimaryQuestions = primaryKey\n    ? selectQuestionsByPrimary(approachCode, primaryKey) ?? []\n    : [];\n  const avoided = primaryKey ? selectAvoidedQuestion(approachCode, primaryKey) : null;\n  const nextStep = primaryKey\n    ? selectNextStepPositioning(approachCode, primaryKey)\n    : null;\n\n  const example = (index: number): string | null =>\n    cleanText(byPrimaryQuestions[index]) || null;\n\n  const sequenceIntro = primaryKey\n    ? [\n        strongest\n          ? `Lead with ${strongest.label} as evidence of what already works, then use ${PILLAR_LABEL[primaryKey]} as the contrast.`\n          : `Lead with the evidence before introducing ${PILLAR_LABEL[primaryKey]}.`,\n        firstSentence(secondaryProfile?.coachingImplication),\n      ]\n        .filter(Boolean)\n        .join(" ")\n    : firstSentence(prosper?.PERMISSION) || null;\n\n  const suggestedSequence: InsiderSequenceStep[] = [\n    {\n      step: 1,\n      title: "Open on the strength, not the constraint",\n      instruction:\n        compact(strongestBlurb) ||\n        (strongest\n          ? `${strongest.label} at ${strongest.percentage}% is the strongest evidence in the result. Use it to establish that the conversation is about protecting what works, not cataloguing deficits.`\n          : firstSentence(prosper?.PERMISSION)),\n      example: strongest\n        ? `What do you recognise in ${strongest.label} as something the business already does well?`\n        : null,\n    },\n    {\n      step: 2,\n      title: "Let them describe the pattern in their own words",\n      instruction:\n        compact(prosper?.OWNERSHIP) ||\n        compact(primaryState?.whatToListenFor) ||\n        compact(prosper?.PERMISSION),\n      example: example(0),\n    },\n    {\n      step: 3,\n      title: "Introduce the contrast, not the diagnosis",\n      instruction:\n        compact(directionalPair?.text) ||\n        compact(falseConstraint?.note) ||\n        compact(pc?.whatIsReallyHappening) ||\n        compact(prosper?.REFRAME),\n      example: example(1) ?? (cleanText(avoided) || null),\n    },\n    {\n      step: 4,\n      title: "Get one commitment, not a plan",\n      instruction:\n        compact(nextStep) ||\n        compact(pc?.coachingPriority) ||\n        compact(prosper?.RESULT),\n      example: example(2),\n    },\n  ];\n\n  const emptySteps = suggestedSequence\n    .filter((step) => !step.instruction)\n    .map((step) => step.step);\n  if (emptySteps.length) {\n    qaFlags.push(`suggested sequence step(s) ${emptySteps.join(", ")} have no selected source content`);\n  }\n\n  const sequenceCaution =\n    compact(primaryState?.whatNotToAssume) ||\n    compact(core?.whatNotToAssumeGeneral) ||\n    null;\n\n  /* ====================================================================== */\n  /* 5. THE OBJECTIVE                                                        */\n  /* ====================================================================== */\n\n  let objective: string | null = null;\n  if (pc?.conversationObjective) {\n    objective = cleanText(pc.conversationObjective);\n  } else if (pc?.coachingPriority) {\n    objective = firstSentence(pc.coachingPriority);\n  } else if (primaryKey) {\n    objective = `Get this ${APPROACH_LABEL[approachCode]} founder to name the ${PILLAR_LABEL[primaryKey]} constraint in their own words and leave with one specific next decision.`;\n    qaFlags.push("objective composed from fallback template — primary-constraint objective missing");\n  } else {\n    objective = `Get this ${APPROACH_LABEL[approachCode]} founder to one diagnosed problem, one recommendation and one clean decision.`;\n    qaFlags.push("objective composed from fallback template — no primary constraint");\n  }\n\n  return {\n    meta: {\n      approachCode,\n      approachLabel: APPROACH_LABEL[approachCode],\n      secondaryInfluence,\n      secondaryInfluenceLabel: secondaryInfluence\n        ? APPROACH_NAME_LABEL[secondaryInfluence]\n        : null,\n      primaryConstraint: primaryKey\n        ? { key: primaryKey, label: PILLAR_LABEL[primaryKey] }\n        : null,\n      secondaryConstraint: secondaryKey\n        ? { key: secondaryKey, label: PILLAR_LABEL[secondaryKey] }\n        : null,\n      strongestPillar: strongest\n        ? {\n            key: strongest.key,\n            label: strongest.label,\n            percentage: strongest.percentage,\n          }\n        : null,\n      sourceVersion: INSIDER_INSIGHTS_SOURCE_VERSION,\n      generatedAt: input.completedAt ?? null,\n      taker: {\n        fullName: cleanText(input.taker?.fullName) || "Unknown",\n        email: cleanText(input.taker?.email),\n        company: cleanText(input.taker?.company),\n      },\n      test: { name: cleanText(input.test?.name) || "The Inevitable Standard" },\n      org: { name: cleanText(input.org?.name) },\n    },\n    snapshot,\n    predictiveSignals,\n    foundersWords,\n    sequenceIntro,\n    suggestedSequence,\n    sequenceCaution,\n    objective,\n    qaFlags,\n  };\n}\n\nexport { PILLAR_LABEL as INSIDER_PILLAR_LABEL, pillarIdFromKey };\n'
TESTS = 'import { describe, expect, it } from "vitest";\n\nimport { buildInsiderInsightsReport } from "./buildInsiderInsightsReport";\nimport { selectPillarState } from "./content/insiderInsights";\n\nfunction fakeScore(overrides: Record<string, unknown> = {}) {\n  return {\n    overall: { percentage: 41.5, label: "Inconsistent" },\n    pillars: {\n      identity: { percentage: 78, risk: "low_risk" },\n      positioning: { percentage: 55, risk: "medium_risk" },\n      offer: { percentage: 60, risk: "medium_risk" },\n      sales: { percentage: 22, risk: "high_risk" },\n      revenue_model: { percentage: 40, risk: "medium_risk" },\n      decision: { percentage: 33, risk: "high_risk" },\n    },\n    approaches: {\n      percentages: { A: 44, B: 20, C: 12, D: 24 },\n      dominant: "A",\n      secondary: "D",\n    },\n    constraints: {\n      primary_constraint: "sales",\n      secondary_constraint: "decision",\n      false_constraint: null,\n      false_constraint_rule_id: null,\n      // Deliberately stale legacy order. Builder must not trust it.\n      priority_fix_order: [\n        "identity",\n        "positioning",\n        "offer",\n        "revenue_model",\n        "sales",\n        "decision",\n      ],\n    },\n    context_answers: {\n      13: "We keep having great conversations that go nowhere. People love the vision but I never actually close.",\n      29: "Whether to raise prices on the new package. I keep putting it off.",\n    },\n    ...overrides,\n  };\n}\n\ndescribe("buildInsiderInsightsReport — approved five-section playbook", () => {\n  it("keeps the approved five-section report contract", () => {\n    const report = buildInsiderInsightsReport({ score: fakeScore() })!;\n    expect(Object.keys(report).sort()).toEqual(\n      [\n        "foundersWords",\n        "meta",\n        "objective",\n        "predictiveSignals",\n        "qaFlags",\n        "sequenceCaution",\n        "sequenceIntro",\n        "snapshot",\n        "suggestedSequence",\n      ].sort(),\n    );\n    expect(report).not.toHaveProperty("sections");\n  });\n\n  it("rebuilds Priority Fix Order from Primary + Secondary instead of stale stored order", () => {\n    const { snapshot } = buildInsiderInsightsReport({ score: fakeScore() })!;\n    expect(snapshot.priorityOrder.map((item) => item.label)).toEqual([\n      "Sales",\n      "Decision",\n      "Revenue Model",\n      "Positioning",\n      "Offer",\n      "Identity",\n    ]);\n  });\n\n  it("snapshot carries the live constraint and strongest-pillar evidence", () => {\n    const { snapshot, meta } = buildInsiderInsightsReport({ score: fakeScore() })!;\n    expect(meta.approachLabel).toBe("Future-Led");\n    expect(snapshot.primaryConstraint?.label).toBe("Sales");\n    expect(snapshot.primaryConstraint?.gar).toBe("RED");\n    expect(snapshot.secondaryConstraint?.label).toBe("Decision");\n    expect(snapshot.strongestPillar?.label).toBe("Identity");\n    expect(snapshot.pillars).toHaveLength(6);\n  });\n\n  it("renders a False Constraint only when the evidence rule matched", () => {\n    expect(buildInsiderInsightsReport({ score: fakeScore() })!.snapshot.falseConstraint).toBeNull();\n\n    const report = buildInsiderInsightsReport({\n      score: fakeScore({\n        constraints: {\n          primary_constraint: "sales",\n          secondary_constraint: "decision",\n          false_constraint: {\n            stated_pillar: "positioning",\n            evidence_pillar: "sales",\n            explanation: "The pattern points to Sales, not lead volume.",\n          },\n          false_constraint_rule_id: "lead_volume",\n          priority_fix_order: ["identity", "positioning", "sales"],\n        },\n      }),\n    })!;\n\n    expect(report.snapshot.falseConstraint?.label.toLowerCase()).toContain("leads");\n    expect(report.snapshot.falseConstraint?.note).toBeTruthy();\n  });\n\n  it("keeps all 13 Figma predictive-signal rows for every approach", () => {\n    const expected = [\n      "How they think",\n      "How they decide",\n      "How they buy",\n      "What builds trust",\n      "What reduces trust",\n      "Best communication style",\n      "Likely objection",\n      "What may really be underneath it",\n      "Buying signals",\n      "Resistance signals",\n      "What to challenge",\n      "What not to assume",\n      "Coaching style",\n    ];\n\n    for (const dominant of ["A", "B", "C", "D"]) {\n      const report = buildInsiderInsightsReport({\n        score: fakeScore({\n          approaches: {\n            percentages: { A: 40, B: 25, C: 20, D: 15 },\n            dominant,\n            secondary: dominant === "A" ? "D" : "A",\n          },\n        }),\n      })!;\n      expect(report.predictiveSignals.map((row) => row.label), dominant).toEqual(expected);\n    }\n  });\n\n  it("uses actual Sales state before generic Connection-Led behaviour", () => {\n    const report = buildInsiderInsightsReport({\n      score: fakeScore({\n        approaches: {\n          percentages: { A: 15, B: 55, C: 15, D: 15 },\n          dominant: "B",\n          secondary: "A",\n        },\n        pillars: {\n          identity: { percentage: 78, risk: "low_risk" },\n          positioning: { percentage: 71, risk: "low_risk" },\n          offer: { percentage: 66, risk: "medium_risk" },\n          sales: { percentage: 82, risk: "low_risk" },\n          revenue_model: { percentage: 54, risk: "medium_risk" },\n          decision: { percentage: 59, risk: "medium_risk" },\n        },\n        constraints: {\n          primary_constraint: "sales",\n          secondary_constraint: "decision",\n          false_constraint: null,\n          false_constraint_rule_id: null,\n          priority_fix_order: [],\n        },\n      }),\n    })!;\n\n    const greenSales = selectPillarState("B", "sales", "GREEN")!;\n    const row = report.predictiveSignals.find((item) => item.label === "How they buy")!;\n    const evidenceLead = (greenSales.howThisAffectsBuying ?? "").replace(/\\s+/g, " ").trim().slice(0, 45);\n    expect(evidenceLead.length).toBeGreaterThan(15);\n    expect(row.text).toContain(evidenceLead);\n  });\n\n  it("uses Red Sales evidence when the Sales result is Red", () => {\n    const report = buildInsiderInsightsReport({\n      score: fakeScore({\n        approaches: {\n          percentages: { A: 15, B: 55, C: 15, D: 15 },\n          dominant: "B",\n          secondary: "A",\n        },\n      }),\n    })!;\n\n    const redSales = selectPillarState("B", "sales", "RED")!;\n    const row = report.predictiveSignals.find((item) => item.label === "How they buy")!;\n    const evidenceLead = (redSales.howThisAffectsBuying ?? "").replace(/\\s+/g, " ").trim().slice(0, 45);\n    expect(row.text).toContain(evidenceLead);\n  });\n\n  it("Q13 shows the Figma four-card evidence strip and all four adviser tags", () => {\n    const report = buildInsiderInsightsReport({\n      score: fakeScore({\n        constraints: {\n          primary_constraint: "sales",\n          secondary_constraint: "decision",\n          false_constraint: {\n            stated_pillar: "positioning",\n            evidence_pillar: "sales",\n            explanation: "Lead volume is not the first intervention.",\n          },\n          false_constraint_rule_id: "lead_volume",\n          priority_fix_order: [],\n        },\n      }),\n    })!;\n\n    const q13 = report.foundersWords.find((item) => item.questionNumber === 13)!;\n    expect(q13.evidencePillars.map((pillar) => pillar.key)).toEqual([\n      "positioning",\n      "offer",\n      "sales",\n      "decision",\n    ]);\n    expect(q13.tags.map((tag) => tag.kind)).toEqual(\n      expect.arrayContaining([\n        "HYPOTHESIS TO VALIDATE",\n        "LISTEN FOR",\n        "DO NOT ASSUME",\n        "GREEN LEVERAGE",\n      ]),\n    );\n    expect(q13.riskSignal).toBeNull();\n  });\n\n  it("Q29 is the answer-level risk surface, matching the approved Figma treatment", () => {\n    const report = buildInsiderInsightsReport({ score: fakeScore() })!;\n    const q29 = report.foundersWords.find((item) => item.questionNumber === 29)!;\n    expect(q29.evidencePillars).toHaveLength(0);\n    expect(q29.tags).toHaveLength(0);\n  });\n\n  it("filler free text does not create Founder Own Words evidence", () => {\n    const report = buildInsiderInsightsReport({\n      score: fakeScore({ context_answers: { 13: "n/a", 29: "" } }),\n    })!;\n    expect(report.foundersWords).toHaveLength(0);\n    expect(report.qaFlags.join(" ")).toContain("Founder\'s Own Words");\n  });\n\n  it("Suggested Sequence uses the four approved Figma moves", () => {\n    const report = buildInsiderInsightsReport({ score: fakeScore() })!;\n    expect(report.suggestedSequence.map((step) => step.title)).toEqual([\n      "Open on the strength, not the constraint",\n      "Let them describe the pattern in their own words",\n      "Introduce the contrast, not the diagnosis",\n      "Get one commitment, not a plan",\n    ]);\n    for (const step of report.suggestedSequence) {\n      expect(step.instruction.length).toBeGreaterThan(0);\n    }\n    expect(report.sequenceIntro).toBeTruthy();\n  });\n\n  it("The Objective remains tailored to the Primary Constraint block", () => {\n    const report = buildInsiderInsightsReport({ score: fakeScore() })!;\n    expect(report.objective).toBeTruthy();\n    expect(report.objective!.length).toBeGreaterThan(20);\n  });\n\n  it("degrades safely without a primary constraint", () => {\n    const report = buildInsiderInsightsReport({\n      score: fakeScore({\n        constraints: {\n          primary_constraint: null,\n          secondary_constraint: null,\n          priority_fix_order: [],\n        },\n      }),\n    })!;\n    expect(report.predictiveSignals).toHaveLength(11);\n    expect(report.suggestedSequence).toHaveLength(4);\n    expect(report.objective).toBeTruthy();\n    expect(report.qaFlags.join(" ")).toContain("primary constraint");\n  });\n\n  it("infers the approach from percentages when dominant is absent", () => {\n    const report = buildInsiderInsightsReport({\n      score: fakeScore({\n        approaches: {\n          percentages: { A: 10, B: 55, C: 20, D: 15 },\n          secondary: "A",\n        },\n      }),\n    })!;\n    expect(report.meta.approachCode).toBe("B");\n    expect(report.qaFlags.join(" ")).toContain("dominant");\n  });\n\n  it("returns null without a usable approach score", () => {\n    expect(buildInsiderInsightsReport({ score: null })).toBeNull();\n    expect(buildInsiderInsightsReport({ score: {} })).toBeNull();\n  });\n\n  it("never leaks source anchors or content IDs into rendered report strings", () => {\n    const banned = [\n      /SOURCE ANCHOR/i,\n      /CONTENT ID:/i,\n      /\\bchapter\\s+(one|two|three|four|five|six|seven|eight|nine|ten|\\d)/i,\n      /\\bappendix\\s+[a-z]\\b/i,\n    ];\n\n    for (const primary of ["identity", "sales", "revenue_model", "decision"]) {\n      for (const dominant of ["A", "B", "C", "D"]) {\n        const report = buildInsiderInsightsReport({\n          score: fakeScore({\n            approaches: {\n              percentages: { A: 40, B: 25, C: 20, D: 15 },\n              dominant,\n              secondary: "D",\n            },\n            constraints: {\n              primary_constraint: primary,\n              secondary_constraint: primary === "sales" ? "decision" : "sales",\n              false_constraint_rule_id: "lead_volume",\n              false_constraint: { explanation: "x" },\n              priority_fix_order: [],\n            },\n          }),\n        })!;\n\n        const strings = [\n          ...report.predictiveSignals.map((row) => row.text),\n          ...report.foundersWords.flatMap((word) => [\n            ...word.tags.map((tag) => tag.text),\n            word.riskSignal?.text ?? "",\n            word.riskSignal?.adviserResponse ?? "",\n          ]),\n          report.sequenceIntro ?? "",\n          ...report.suggestedSequence.flatMap((step) => [\n            step.instruction,\n            step.example ?? "",\n          ]),\n          report.sequenceCaution ?? "",\n          report.objective ?? "",\n          report.snapshot.falseConstraint?.note ?? "",\n        ];\n\n        for (const value of strings) {\n          for (const pattern of banned) {\n            expect(value, `${dominant}/${primary}`).not.toMatch(pattern);\n          }\n        }\n      }\n    }\n  });\n});\n'
UI = '"use client";\n\nimport Link from "next/link";\nimport { useEffect, useMemo, useState, type ReactNode } from "react";\n\nimport type {\n  InsiderFounderWord,\n  InsiderInsightsReport,\n  InsiderPillarSnapshot,\n  InsiderSequenceStep,\n} from "@/lib/inevitable-standard/buildInsiderInsightsReport";\nimport {\n  GOLD,\n  HAIRLINE,\n  INK,\n  NAVY_DEEP,\n  ReadinessDonut,\n  newsreader,\n  round1,\n  serif,\n} from "@/app/t/[token]/report/inevitableStandardShared";\nimport PrintButton from "@/app/t/[token]/report/PrintButton";\n\nconst FIGMA = {\n  page: "#041731",\n  navy: "#14263d",\n  navy2: "#1f2c46",\n  panel: "#edeff2",\n  ivory: "#f8f6f1",\n  gold: "#b89a5e",\n  goldLight: "#c9b98f",\n  body: "#66727d",\n  hairline: "#d6dae0",\n  border: "#ddd4bd",\n  green: "#4c7a5b",\n  amber: "#bd8b3d",\n  red: "#a8503f",\n};\n\nconst GAR_TONE = {\n  GREEN: { colour: FIGMA.green, bg: "#e2ebe0", risk: "LOW RISK" },\n  AMBER: { colour: FIGMA.amber, bg: "#f1e5cc", risk: "MEDIUM RISK" },\n  RED: { colour: FIGMA.red, bg: "#f1ddd6", risk: "HIGH RISK" },\n} as const;\n\nconst PILLAR_ICON: Record<InsiderPillarSnapshot["key"], string> = {\n  identity: "/inevitable-standard/snapshot/identitiy.png",\n  positioning: "/inevitable-standard/snapshot/positioning.png",\n  offer: "/inevitable-standard/snapshot/offer.png",\n  sales: "/inevitable-standard/snapshot/sales.png",\n  revenue_model: "/inevitable-standard/snapshot/revenue-model.png",\n  decision: "/inevitable-standard/snapshot/decision.png",\n};\n\nconst SIGNAL_ICON: Record<string, string> = {\n  "How they think": "/inevitable-standard/insider-insights/Brain.png",\n  "How they decide": "/inevitable-standard/insider-insights/Stopwatch.png",\n  "How they buy": "/inevitable-standard/insider-insights/Buy.png",\n  "What builds trust": "/inevitable-standard/insider-insights/Guarantee.png",\n  "What reduces trust": "/inevitable-standard/insider-insights/Cancel.png",\n  "Best communication style": "/inevitable-standard/insider-insights/Solve.png",\n  "Likely objection": "/inevitable-standard/insider-insights/Error.png",\n  "What may really be underneath it": "/inevitable-standard/insider-insights/Search.png",\n  "Buying signals": "/inevitable-standard/insider-insights/Flag.png",\n  "Resistance signals": "/inevitable-standard/insider-insights/Refresh.png",\n  "What to challenge": "/inevitable-standard/insider-insights/Challange.png",\n  "What not to assume": "/inevitable-standard/insider-insights/Eye.png",\n  "Coaching style": "/inevitable-standard/insider-insights/Clipboard%20List.png",\n};\n\nconst INDEX_ITEMS = [\n  { id: "snapshot", label: "Insider snapshot" },\n  { id: "predictive-signals", label: "Predictive signals at a glance" },\n  { id: "founders-words", label: "Founder\'s own words" },\n  { id: "suggested-sequence", label: "Suggested sequence" },\n  { id: "objective", label: "The Objective" },\n] as const;\n\nconst TAG_LABEL_TONE: Record<\n  InsiderFounderWord["tags"][number]["kind"],\n  string\n> = {\n  "HYPOTHESIS TO VALIDATE": "#b3893f",\n  "LISTEN FOR": "#b3893f",\n  "DO NOT ASSUME": "#a8503f",\n  "GREEN LEVERAGE": "#4c7a5b",\n};\n\nfunction SectionShell({\n  id,\n  eyebrow,\n  children,\n}: {\n  id: string;\n  eyebrow: string;\n  children: ReactNode;\n}) {\n  return (\n    <section\n      id={id}\n      className="scroll-mt-6 rounded-[20px] p-[27px] print:break-inside-avoid"\n      style={{ backgroundColor: FIGMA.navy }}\n    >\n      <p\n        className="text-[14px] font-semibold uppercase tracking-[0.18em] sm:text-[16px]"\n        style={{ color: FIGMA.gold }}\n      >\n        {eyebrow}\n      </p>\n      <div\n        className="mt-[26px] rounded-[20px] p-6 sm:p-10"\n        style={{ backgroundColor: FIGMA.panel }}\n      >\n        {children}\n      </div>\n    </section>\n  );\n}\n\nfunction RiskChip({ pillar }: { pillar: InsiderPillarSnapshot }) {\n  const tone = GAR_TONE[pillar.gar];\n  return (\n    <span\n      className="inline-flex rounded-full px-2.5 py-1 text-[9px] font-bold uppercase tracking-[0.08em]"\n      style={{ backgroundColor: tone.bg, color: tone.colour }}\n    >\n      {round1(pillar.percentage)}% · {tone.risk}\n    </span>\n  );\n}\n\nfunction HeroPillars({ pillars }: { pillars: InsiderPillarSnapshot[] }) {\n  return (\n    <div className="rounded-[10px] border border-white/15 bg-white/[0.05] px-7 py-5">\n      <p className="mb-4 text-[10px] uppercase tracking-[0.16em] text-[#a9a08a]">\n        The six pillars\n      </p>\n      <div className="space-y-[13px]">\n        {pillars.map((pillar) => {\n          const tone = GAR_TONE[pillar.gar];\n          return (\n            <div\n              key={pillar.key}\n              className="grid grid-cols-[105px_1fr_34px] items-center gap-3"\n            >\n              <div className="flex items-center gap-2">\n                <img\n                  src={PILLAR_ICON[pillar.key]}\n                  alt=""\n                  className="h-6 w-6 object-contain"\n                />\n                <span className="text-[11px] text-[#cfc9b8]">\n                  {pillar.key === "revenue_model" ? "Rev. Model" : pillar.label}\n                </span>\n              </div>\n              <div className="h-[6px] overflow-hidden rounded-full bg-white/15">\n                <div\n                  className="h-full rounded-full"\n                  style={{\n                    width: `${pillar.percentage}%`,\n                    backgroundColor: tone.colour,\n                  }}\n                />\n              </div>\n              <span className="text-right text-[11px] font-bold text-[#f0ece0]">\n                {round1(pillar.percentage)}%\n              </span>\n            </div>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n\nfunction PillarStrip({ pillars }: { pillars: InsiderPillarSnapshot[] }) {\n  return (\n    <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 xl:grid-cols-6">\n      {pillars.map((pillar) => {\n        const tone = GAR_TONE[pillar.gar];\n        return (\n          <div\n            key={pillar.key}\n            className="rounded-[6px] border-t-2 px-3 pb-2 pt-3"\n            style={{\n              borderColor: tone.colour,\n              backgroundColor: `${tone.colour}24`,\n            }}\n          >\n            <p className="text-[8px] font-bold uppercase tracking-[0.1em] text-[#14263d]">\n              {pillar.label}\n            </p>\n            <p className="mt-1 text-[21px]" style={{ ...serif, color: FIGMA.navy }}>\n              {round1(pillar.percentage)}\n            </p>\n          </div>\n        );\n      })}\n    </div>\n  );\n}\n\nfunction QuickReferenceRow({\n  label,\n  children,\n  last = false,\n}: {\n  label: string;\n  children: ReactNode;\n  last?: boolean;\n}) {\n  return (\n    <div\n      className="grid gap-2 py-3.5 sm:grid-cols-[220px_1fr] sm:items-center"\n      style={{\n        borderBottom: last ? undefined : `1px dashed ${FIGMA.border}`,\n      }}\n    >\n      <dt className="text-[10px] font-bold uppercase tracking-[0.1em] text-[#736c5c]">\n        {label}\n      </dt>\n      <dd className="text-[14px] leading-6 text-[#26241d]">{children}</dd>\n    </div>\n  );\n}\n\nfunction EvidenceStrip({ pillars }: { pillars: InsiderPillarSnapshot[] }) {\n  if (pillars.length === 0) return null;\n  return (\n    <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">\n      {pillars.map((pillar) => {\n        const tone = GAR_TONE[pillar.gar];\n        return (\n          <div\n            key={pillar.key}\n            className="rounded-[10px] border-t-2 bg-white px-4 py-4"\n            style={{ borderColor: tone.colour }}\n          >\n            <p className="text-[8px] uppercase tracking-[0.1em] text-[#66727d]">\n              {pillar.label}\n            </p>\n            <p className="mt-2 text-[16px]" style={{ ...serif, color: FIGMA.navy }}>\n              {pillar.garLabel} {round1(pillar.percentage)}\n            </p>\n          </div>\n        );\n      })}\n    </div>\n  );\n}\n\nfunction FounderWord({ item }: { item: InsiderFounderWord }) {\n  return (\n    <div className="space-y-[18px]">\n      <div className="rounded-[15px] p-7" style={{ backgroundColor: FIGMA.ivory }}>\n        <p\n          className="text-[9px] font-bold uppercase tracking-[0.16em]"\n          style={{ color: FIGMA.gold }}\n        >\n          Founder&apos;s own words · Question {item.questionNumber}\n        </p>\n        <blockquote\n          className="mt-3 text-[20px] leading-8 sm:text-[21px]"\n          style={{ ...serif, color: FIGMA.navy }}\n        >\n          “{item.quote}”\n        </blockquote>\n      </div>\n\n      <EvidenceStrip pillars={item.evidencePillars} />\n\n      {item.tags.length > 0 ? (\n        <div\n          className="rounded-[6px] border bg-white px-7 py-6"\n          style={{ borderColor: FIGMA.border }}\n        >\n          <div className="space-y-5">\n            {item.tags.map((tag) => (\n              <div key={tag.kind}>\n                <p\n                  className="text-[10px] font-bold uppercase tracking-[0.08em]"\n                  style={{ color: TAG_LABEL_TONE[tag.kind] }}\n                >\n                  {tag.kind}\n                </p>\n                <p className="mt-2 text-[14px] leading-6 text-[#66727d]">\n                  {tag.text}\n                </p>\n              </div>\n            ))}\n          </div>\n        </div>\n      ) : null}\n\n      {item.riskSignal ? (\n        <div className="rounded-[15px] p-7" style={{ backgroundColor: FIGMA.ivory }}>\n          <span className="inline-block bg-[#8a4a3d] px-3 py-1 text-[9px] font-bold uppercase tracking-[0.14em] text-white">\n            Risk signal\n          </span>\n          <p className="mt-3 text-[13px] leading-6 text-[#66727d]">\n            {item.riskSignal.text}\n          </p>\n          {item.riskSignal.adviserResponse ? (\n            <p className="mt-3 text-[12px] leading-5 text-[#8a4a3d]">\n              Adviser response: {item.riskSignal.adviserResponse}\n            </p>\n          ) : null}\n        </div>\n      ) : null}\n    </div>\n  );\n}\n\nfunction SequenceStep({ step }: { step: InsiderSequenceStep }) {\n  return (\n    <div\n      className="grid grid-cols-[48px_1fr] gap-5 border-b py-5 last:border-b-0"\n      style={{ borderColor: FIGMA.hairline }}\n    >\n      <span\n        className="text-[30px] leading-none"\n        style={{ ...serif, color: FIGMA.gold }}\n      >\n        {String(step.step).padStart(2, "0")}\n      </span>\n      <div>\n        <h3 className="text-[17px] capitalize" style={{ ...serif, color: FIGMA.navy }}>\n          {step.title}\n        </h3>\n        <p className="mt-2 text-[12px] leading-5 text-[#14263d]">\n          {step.instruction}\n        </p>\n        {step.example ? (\n          <p\n            className="mt-3 text-[14px] italic leading-6 text-[#1e3550]"\n            style={serif}\n          >\n            “{step.example}”\n          </p>\n        ) : null}\n      </div>\n    </div>\n  );\n}\n\nexport default function InsiderInsightsReportClient({\n  report,\n  backHref,\n}: {\n  report: InsiderInsightsReport;\n  backHref: string;\n}) {\n  const { meta, snapshot } = report;\n  const [activeSection, setActiveSection] = useState<string>("snapshot");\n\n  const indexItems = useMemo(\n    () =>\n      INDEX_ITEMS.filter((item) => {\n        if (item.id === "founders-words") return report.foundersWords.length > 0;\n        if (item.id === "predictive-signals") return report.predictiveSignals.length > 0;\n        if (item.id === "objective") return Boolean(report.objective);\n        return true;\n      }),\n    [report],\n  );\n\n  useEffect(() => {\n    if (typeof IntersectionObserver === "undefined") return;\n    const elements = indexItems\n      .map((item) => document.getElementById(item.id))\n      .filter((element): element is HTMLElement => Boolean(element));\n\n    if (elements.length === 0) return;\n\n    const observer = new IntersectionObserver(\n      (entries) => {\n        const visible = entries\n          .filter((entry) => entry.isIntersecting)\n          .sort((a, b) => b.intersectionRatio - a.intersectionRatio);\n        if (visible[0]) setActiveSection(visible[0].target.id);\n      },\n      { rootMargin: "-15% 0px -65% 0px", threshold: [0, 0.25, 0.6, 1] },\n    );\n\n    elements.forEach((element) => observer.observe(element));\n    return () => observer.disconnect();\n  }, [indexItems]);\n\n  const completedLabel = meta.generatedAt\n    ? new Date(meta.generatedAt).toLocaleDateString(undefined, {\n        year: "numeric",\n        month: "long",\n        day: "numeric",\n      })\n    : "—";\n\n  const secondaryText = snapshot.secondaryApproach\n    ? snapshot.secondaryApproach.percentage != null\n      ? `${snapshot.secondaryApproach.label} — ${round1(snapshot.secondaryApproach.percentage)}%`\n      : snapshot.secondaryApproach.label\n    : "—";\n\n  return (\n    <main\n      className={`${newsreader.variable} min-h-screen`}\n      style={{ backgroundColor: FIGMA.page, color: INK }}\n    >\n      {/* Keep platform/help overlays out of generated PDFs. */}\n      <style>{`\n        @media print {\n          body .fixed,\n          body [style*="position: fixed"],\n          body [style*="position:fixed"],\n          body [aria-label*="chat" i],\n          body .intercom-lightweight-app,\n          body .crisp-client {\n            display: none !important;\n          }\n        }\n      `}</style>\n\n      {/* Approved Figma top bar */}\n      <header\n        className="border-b border-white/10 px-5 py-4 text-white print:hidden"\n        style={{ backgroundColor: FIGMA.navy }}\n      >\n        <div className="mx-auto flex max-w-[1400px] flex-wrap items-center gap-4">\n          <Link href={backHref} className="mr-auto flex min-w-[330px] items-center gap-4">\n            <div className="flex h-11 w-11 items-center justify-center rounded-2xl border border-white/15 bg-white/10">\n              <img\n                src="/images/profile-test-ai-logo.png"\n                alt="profiletest.ai"\n                className="max-h-8 max-w-8 object-contain brightness-0 invert"\n              />\n            </div>\n            <div>\n              <p className="text-[18px] font-semibold uppercase tracking-[0.14em] sm:text-[24px]">\n                Insider Insights\n              </p>\n              <p\n                className="mt-1 text-[9px] font-semibold uppercase tracking-[0.24em]"\n                style={{ color: FIGMA.goldLight }}\n              >\n                The Inevitable Standard Method™ · Powered By profiletest-ai\n              </p>\n            </div>\n          </Link>\n\n          <PrintButton\n            className="rounded-lg px-5 py-2 text-[12px] font-semibold text-white"\n            style={{ backgroundColor: FIGMA.gold }}\n          >\n            Download PDF\n          </PrintButton>\n\n          <div className="grid grid-cols-2 gap-2 text-[10px]">\n            <div className="rounded-[18px] border border-white/30 px-4 py-2">\n              <span className="block text-white/40">Prepared for</span>\n              <strong className="mt-1 block text-[12px] text-white">Coaches</strong>\n            </div>\n            <div className="rounded-[18px] border border-white/30 px-4 py-2">\n              <span className="block text-white/40">Date</span>\n              <strong className="mt-1 block text-[12px] text-white">{completedLabel}</strong>\n            </div>\n          </div>\n        </div>\n      </header>\n\n      {/* Approved Figma hero */}\n      <section className="bg-gradient-to-b from-[#14263d] to-[#1f2c46] px-6 py-[60px] text-white sm:px-10">\n        <div className="mx-auto grid max-w-[1275px] gap-8 xl:grid-cols-[1fr_676px]">\n          <div>\n            <p className="text-[12px] uppercase tracking-[0.18em]" style={{ color: FIGMA.gold }}>\n              The Inevitable Standard Method™\n            </p>\n            <h1 className="mt-6 text-[52px] leading-[0.98] sm:text-[68px] xl:text-[80px]" style={serif}>\n              Insider Insights\n            </h1>\n            <p\n              className="mt-5 text-[24px] italic sm:text-[30px]"\n              style={{ ...serif, color: FIGMA.goldLight }}\n            >\n              Predictive Selling &amp; Coaching Playbook\n            </p>\n            <div className="mt-8 border-t border-[#b89a5e]/45 pt-3 text-[11px] uppercase tracking-[0.2em]">\n              Prepared for {meta.taker.fullName}\n            </div>\n            <p className="mt-5 max-w-[660px] text-[11px] leading-[18px] text-[#8e9aaa]">\n              This document is prepared for the adviser, coach or consultant conducting\n              the commercial conversation. It is not supplied to the test taker. It\n              contains interpretation and hypotheses, not conclusions.\n            </p>\n          </div>\n\n          <div>\n            <div className="grid gap-6 sm:grid-cols-[263px_1fr]">\n              <div className="flex flex-col items-center rounded-[10px] border border-white/15 bg-white/[0.05] px-5 py-4">\n                <p className="text-center text-[10px] uppercase tracking-[0.14em] text-[#a9a08a]">\n                  Inevitable Standard Readiness\n                </p>\n                <ReadinessDonut\n                  percentage={snapshot.readinessPercentage}\n                  band={snapshot.readinessLabel ?? ""}\n                />\n                <p className="text-center text-[13px] text-[#e8e2d0]">\n                  {snapshot.readinessLabel || "Current result"}{" "}\n                  <span className="text-[#cfc9b8]">· Current standard</span>\n                </p>\n              </div>\n              <HeroPillars pillars={snapshot.pillars} />\n            </div>\n            <div className="mt-8 flex justify-end">\n              <span className="bg-[#a85b55] px-7 py-5 text-[11px] uppercase tracking-[0.22em] text-white">\n                Internal use only\n              </span>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <div className="mx-auto grid max-w-[1275px] gap-[46px] px-5 py-14 lg:grid-cols-[303px_minmax(0,963px)]">\n        {/* Approved Figma sidebar */}\n        <aside className="print:hidden">\n          <div\n            className="sticky top-5 rounded-[20px] border border-white/10 p-[18px]"\n            style={{ backgroundColor: FIGMA.ivory }}\n          >\n            <p className="mb-4 text-[11px] uppercase tracking-[0.24em] text-[#33445a]">\n              Report Index\n            </p>\n            <nav className="space-y-2">\n              {indexItems.map((item, index) => {\n                const active = item.id === activeSection;\n                return (\n                  <a\n                    key={item.id}\n                    href={`#${item.id}`}\n                    aria-current={active ? "true" : undefined}\n                    className="block rounded-[15px] border px-4 py-3 text-[12px] leading-5 transition"\n                    style={\n                      active\n                        ? {\n                            backgroundColor: "#33445a",\n                            borderColor: "#33445a",\n                            color: "#fff",\n                          }\n                        : { borderColor: "#33445a", color: "#33445a" }\n                    }\n                  >\n                    {index + 1}. {item.label}\n                  </a>\n                );\n              })}\n            </nav>\n            <PrintButton className="mt-3 w-full rounded-[10px] bg-[#33445a] px-4 py-3 text-[12px] font-semibold text-white">\n              Download PDF\n            </PrintButton>\n            <a\n              href="#suggested-sequence"\n              className="mt-2 block w-full rounded-[10px] bg-gradient-to-r from-[#5a7a9e] via-[#2563c8] to-[#14263d] px-4 py-3 text-center text-[12px] font-semibold text-white"\n            >\n              Next step\n            </a>\n          </div>\n        </aside>\n\n        <div className="space-y-10">\n          {/* 1. Quick reference */}\n          <SectionShell id="snapshot" eyebrow="Quick Reference">\n            <h2 className="text-[29px]" style={{ ...serif, color: FIGMA.navy }}>\n              Insider snapshot\n            </h2>\n\n            <dl\n              className="mt-7 rounded-[10px] border bg-white px-7 py-6"\n              style={{ borderColor: FIGMA.border }}\n            >\n              <QuickReferenceRow label="Client">\n                <strong className="text-[#182238]">{meta.taker.fullName}</strong>\n                <span className="block">\n                  {[meta.taker.company, completedLabel && `Completed ${completedLabel}`]\n                    .filter(Boolean)\n                    .join(" · ")}\n                </span>\n              </QuickReferenceRow>\n\n              <QuickReferenceRow label="Primary Decision Approach">\n                {snapshot.primaryApproach.label} — {round1(snapshot.primaryApproach.percentage)}%\n              </QuickReferenceRow>\n\n              <QuickReferenceRow label="Secondary Influence">\n                {secondaryText}\n              </QuickReferenceRow>\n\n              <QuickReferenceRow label="Overall Readiness">\n                {round1(snapshot.readinessPercentage)}% — {snapshot.readinessLabel || "—"}\n              </QuickReferenceRow>\n\n              <QuickReferenceRow label="Primary Constraint">\n                {snapshot.primaryConstraint ? (\n                  <span className="flex flex-wrap items-center gap-2">\n                    {snapshot.primaryConstraint.label}\n                    <RiskChip pillar={snapshot.primaryConstraint} />\n                  </span>\n                ) : (\n                  "—"\n                )}\n              </QuickReferenceRow>\n\n              <QuickReferenceRow label="Secondary Constraint">\n                {snapshot.secondaryConstraint ? (\n                  <span className="flex flex-wrap items-center gap-2">\n                    {snapshot.secondaryConstraint.label}\n                    <RiskChip pillar={snapshot.secondaryConstraint} />\n                  </span>\n                ) : (\n                  "—"\n                )}\n              </QuickReferenceRow>\n\n              <QuickReferenceRow label="Strongest Pillar">\n                {snapshot.strongestPillar ? (\n                  <span className="flex flex-wrap items-center gap-2">\n                    {snapshot.strongestPillar.label}\n                    <RiskChip pillar={snapshot.strongestPillar} />\n                  </span>\n                ) : (\n                  "—"\n                )}\n              </QuickReferenceRow>\n\n              <QuickReferenceRow label="Possible False Constraint">\n                {snapshot.falseConstraint?.label || "None flagged"}\n              </QuickReferenceRow>\n\n              <QuickReferenceRow label="Priority Fix Order" last>\n                {snapshot.priorityOrder.map((item) => item.label).join(" → ")}\n              </QuickReferenceRow>\n            </dl>\n\n            <div className="mt-7">\n              <PillarStrip pillars={snapshot.pillars} />\n            </div>\n          </SectionShell>\n\n          {/* 2. Predictive signals */}\n          {report.predictiveSignals.length > 0 ? (\n            <SectionShell id="predictive-signals" eyebrow="Before the Conversation">\n              <h2 className="text-[29px]" style={{ ...serif, color: FIGMA.navy }}>\n                Predictive signals at a glance\n              </h2>\n              <div className="mt-6 grid bg-white md:grid-cols-2">\n                {report.predictiveSignals.map((row, index) => {\n                  const last = index === report.predictiveSignals.length - 1;\n                  return (\n                    <div\n                      key={row.label}\n                      className={`border-b px-5 py-4 ${last ? "md:col-span-2" : ""}`}\n                      style={{ borderColor: FIGMA.hairline }}\n                    >\n                      <div className="flex items-center gap-3">\n                        {SIGNAL_ICON[row.label] ? (\n                          <img\n                            src={SIGNAL_ICON[row.label]}\n                            alt=""\n                            className="h-[22px] w-[22px] object-contain"\n                          />\n                        ) : null}\n                        <p\n                          className="text-[9px] font-semibold uppercase tracking-[0.14em]"\n                          style={{ color: FIGMA.gold }}\n                        >\n                          {row.label}\n                        </p>\n                      </div>\n                      <p className="mt-2 text-[12px] leading-[18px] text-[#14263d]">\n                        {row.text}\n                      </p>\n                    </div>\n                  );\n                })}\n              </div>\n            </SectionShell>\n          ) : null}\n\n          {/* 3. Founder\'s own words */}\n          {report.foundersWords.length > 0 ? (\n            <SectionShell id="founders-words" eyebrow="Diagnostic Interpretation">\n              <h2 className="text-[29px]" style={{ ...serif, color: FIGMA.navy }}>\n                Founder&apos;s own words\n              </h2>\n              <div className="mt-6 space-y-8">\n                {report.foundersWords.map((item) => (\n                  <FounderWord key={item.questionNumber} item={item} />\n                ))}\n              </div>\n            </SectionShell>\n          ) : null}\n\n          {/* 4. Suggested sequence */}\n          <SectionShell id="suggested-sequence" eyebrow="In the Conversation">\n            <h2 className="text-[29px]" style={{ ...serif, color: FIGMA.navy }}>\n              Suggested sequence\n            </h2>\n            {report.sequenceIntro ? (\n              <p className="mt-3 text-[14px] leading-6 text-[#66727d]">\n                {report.sequenceIntro}\n              </p>\n            ) : null}\n\n            <div className="mt-5 border-t" style={{ borderColor: FIGMA.hairline }}>\n              {report.suggestedSequence.map((step) => (\n                <SequenceStep key={step.step} step={step} />\n              ))}\n            </div>\n\n            {report.sequenceCaution ? (\n              <div className="mt-6 rounded-[10px] border-l-2 bg-white px-6 py-5" style={{ borderColor: FIGMA.red }}>\n                <span className="inline-block bg-[#a85b55] px-3 py-1 text-[9px] font-bold uppercase tracking-[0.14em] text-white">\n                  Do not assume\n                </span>\n                <p className="mt-3 text-[12px] leading-5 text-[#14263d]">\n                  {report.sequenceCaution}\n                </p>\n              </div>\n            ) : null}\n          </SectionShell>\n\n          {/* 5. Objective */}\n          {report.objective ? (\n            <section\n              id="objective"\n              className="scroll-mt-6 rounded-[20px] bg-gradient-to-r from-[#14263d] to-[#1f2c46] px-8 py-12 text-center text-white shadow-xl print:break-inside-avoid"\n            >\n              <p\n                className="text-[15px] font-medium uppercase tracking-[0.18em]"\n                style={{ color: FIGMA.gold }}\n              >\n                The Objective\n              </p>\n              <h2 className="mt-5 text-[27px]" style={serif}>\n                What this conversation needs to achieve\n              </h2>\n              <p className="mt-3 text-[11px] text-[#8e9aaa]">\n                Everything else in this playbook is optional. If the conversation\n                achieves only one thing, it should be this.\n              </p>\n              <div\n                className="mx-auto mt-8 max-w-[715px] rounded-[15px] border-2 px-8 py-9"\n                style={{ borderColor: FIGMA.gold }}\n              >\n                <p\n                  className="text-[10px] font-bold uppercase tracking-[0.18em]"\n                  style={{ color: FIGMA.gold }}\n                >\n                  The one thing this conversation needs to achieve\n                </p>\n                <p className="mt-4 text-[23px] leading-8 sm:text-[25px]" style={serif}>\n                  {report.objective}\n                </p>\n              </div>\n            </section>\n          ) : null}\n\n          <footer className="pb-4 text-[11px] text-[#8e9aaa] print:hidden">\n            Content source: {meta.sourceVersion}.\n            {report.qaFlags.length > 0 ? (\n              <details className="mt-2">\n                <summary className="cursor-pointer">\n                  Diagnostic notes ({report.qaFlags.length})\n                </summary>\n                <ul className="mt-2 list-disc space-y-1 pl-5">\n                  {report.qaFlags.map((flag, index) => (\n                    <li key={index}>{flag}</li>\n                  ))}\n                </ul>\n              </details>\n            ) : null}\n          </footer>\n        </div>\n      </div>\n    </main>\n  );\n}\n'

def current_branch():
    try:
        return subprocess.check_output(
            ["git", "rev-parse", "--abbrev-ref", "HEAD"],
            cwd=ROOT,
            text=True,
            stderr=subprocess.DEVNULL,
        ).strip()
    except Exception:
        return ""

missing = [str(path) for path in FILES.values() if not path.exists()]
if missing:
    print("Missing expected files:")
    for path in missing:
        print("  -", path)
    print("\nRun this script from the mindcanvas-brain repository root.")
    sys.exit(1)

branch = current_branch()
if branch and branch not in {"feature/inevitable-standard", "fix/inevitable-report-alignment"}:
    print(f"Current branch is {branch!r}.")
    print("Switch to feature/inevitable-standard (or a fix branch from it) before applying.")
    sys.exit(1)

# Guard against accidentally running against a materially different Insider implementation.
builder_now = FILES["builder"].read_text(encoding="utf-8")
ui_now = FILES["ui"].read_text(encoding="utf-8")
if "buildInsiderInsightsReport" not in builder_now or "predictiveSignals" not in builder_now:
    print("Insider builder no longer matches the expected implementation; no files written.")
    sys.exit(1)
if "InsiderInsightsReportClient" not in ui_now or "Insider Snapshot" not in ui_now:
    print("Insider report client no longer matches the expected implementation; no files written.")
    sys.exit(1)

FILES["builder"].write_text(BUILDER, encoding="utf-8")
FILES["tests"].write_text(TESTS, encoding="utf-8")
FILES["ui"].write_text(UI, encoding="utf-8")

print("Applied Insider Insights alignment to:")
for path in FILES.values():
    print("  -", path.relative_to(ROOT))

print("\nWhat changed:")
print("  - preserved the approved five-section Figma information architecture")
print("  - rebuilt stale Priority Fix Order from Primary + Secondary + severity")
print("  - made pillar/constraint evidence outrank generic approach copy")
print("  - matched the Figma Q13 evidence strip and adviser tags")
print("  - matched the Figma four-step conversation sequence and Objective treatment")
print("  - added print-only suppression for fixed/chat support overlays")

print("\nNo commit, push, merge, or deployment was performed.")
print("\nRun next:")
print("  pnpm --dir apps/web exec vitest run lib/inevitable-standard/buildInsiderInsightsReport.test.ts")
print("  pnpm --dir apps/web exec vitest run lib/inevitable-standard/constraintEngine.test.ts")
print("  pnpm --dir apps/web run typecheck")
print("  git diff --check")
